import Storage from"../../services/Storage.js";import{favoriteMixin}from"./favorite-mixin.js";import{categorySubject}from"./category-subject.js";let blogsList=[],currentCategory=null,currentRoot=document;const applyCategoryFilter=t=>{currentCategory=t||null;const e=currentCategory?blogsList.filter(t=>t.category===currentCategory):blogsList;renderer.render(e,currentRoot)};class BlogRenderer{render(t,e=document){const r=e.querySelector(".blog__container");r&&(r.innerHTML=t.map(t=>{const e=Storage.isFavorite(t.id)?"★":"☆";return`\n            <div class="blog__article">\n                <img src="${t.image}" alt="${t.title}" class="blog__article-image">\n                <div class="blog__article-info">\n                    <h4 class="blog__article-title">${t.title}</h4>\n                    <button class="blog__favorite" data-id="${t.id}" \n                        style="font-size: 24px; background: none; border: none; cursor: pointer;">\n                        ${e}\n                    </button>\n                </div>\n            </div>`}).join("\n"),this.attachFavoriteHandlers(e))}}Object.assign(BlogRenderer.prototype,favoriteMixin);const renderer=new BlogRenderer;export const init_blogs=async(t=document)=>{if(currentRoot=t,!blogsList.length){const t=await fetch("/data/blogs.json");blogsList=await t.json()}categorySubject.addObserver(applyCategoryFilter);const e=currentCategory?blogsList.filter(t=>t.category===currentCategory):blogsList;renderer.render(e,currentRoot)};